-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
CREATE OR REPLACE VIEW intermediate.sat_customer_current AS
with versions as (

    select * from intermediate.sat_customer

)

select
    versions.hub_customer_hk as hub_customer_hk,
    versions.customer_number as customer_number,
    versions.customer_name as customer_name,
    versions.market_segment as market_segment,
    versions.account_balance as account_balance,
    versions.hashdiff as hashdiff,
    versions.load_date as load_date,
    versions.record_source as record_source
from versions
where versions.load_date = (select max(latest.load_date) from intermediate.sat_customer as latest where latest.hub_customer_hk = versions.hub_customer_hk);
